for _lang, _entries in _GLOBAL_TRANSLATION_BACKFILL.items():
    TRANSLATIONS.setdefault(_lang, {}).update(_entries)


def tr(key: str, default: str = None):
    try:
        lang = mw.pm.profile.get('onigiri_language', 'en')
    except:
        lang = 'en'
    if lang not in TRANSLATIONS:
        lang = 'en'
    return TRANSLATIONS[lang].get(key, TRANSLATIONS['en'].get(key, default or key))


def current_language() -> str:
    try:
        lang = mw.pm.profile.get('onigiri_language', 'en')
    except Exception:
        lang = 'en'
    return lang if lang in TRANSLATIONS else 'en'


def current_locale():
    """QLocale matching the add-on's configured language (not the OS locale),
    so weekday/month names line up with the rest of the translated UI."""
    from PyQt6.QtCore import QLocale
    return QLocale(current_language())
